import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 18 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * Practice Tests 1–17.
 */

// ─────────────────────── PRACTICE TEST 18 · R&W M1 (27) ──────────────────────
const T18_RW_M1: SatQuestion[] = [
  { id: "t18rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The clockmaker's apprentice was praised for her ______ hands, fitting gears no wider than a grain of rice without ever slipping.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["deft", "clumsy", "idle", "weary"], correct: 0, explanation: "The answer is \"deft.\" The sentence says she fits gears \"no wider than a grain of rice without ever slipping,\" which describes skillful, nimble hands, and \"deft\" means exactly that. \"Clumsy\" means awkward and prone to slipping, the opposite of what the praise describes. \"Idle\" means inactive, but her hands are clearly working with precision. \"Weary\" means tired, which says nothing about the manual skill the sentence emphasizes." },
  { id: "t18rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of judges ______ reviewing the final entries before announcing a winner.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "The answer is \"is.\" Rule: a verb agrees with its grammatical subject, not with a noun inside an intervening prepositional phrase. The subject is the singular collective noun \"committee\"; \"of judges\" is just a modifier, so the singular \"is\" is required. \"are\" is plural and wrongly agrees with \"judges\" rather than \"committee.\" \"have been\" is also plural and mismatches the singular head noun. \"were\" is plural and past tense, doubly wrong for a singular subject in a present-tense sentence." },
  { id: "t18rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Tardigrades, microscopic animals barely half a millimeter long, can survive boiling, freezing, and even the vacuum of space by entering a dried-out, near-dead state called cryptobiosis until conditions improve.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Tardigrades endure extreme conditions by entering a dormant survival state.", "Tardigrades can only live in warm water.", "Tardigrades grow larger in the vacuum of space.", "Tardigrades die instantly when frozen."], correct: 0, explanation: "The answer is A. The text says tardigrades \"can survive boiling, freezing, and even the vacuum of space by entering a dried-out, near-dead state called cryptobiosis,\" which A restates as enduring extremes through a dormant survival state. B is contradicted because surviving boiling, freezing, and vacuum shows the animals are not limited to warm water. C reverses the text, which describes a shrunken, near-dead state, not growth, in the vacuum of space. D contradicts the passage outright, since the text says tardigrades survive freezing rather than dying instantly when frozen." },
  { id: "t18rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The reservoir had dropped to a record low. ______, the town introduced strict limits on lawn watering.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "Similarly"], correct: 1, explanation: "The answer is \"Consequently.\" The watering limits are an effect caused by the record-low reservoir, and \"Consequently\" is the transition that signals a result. \"Nevertheless\" signals concession or contrast, but the limits follow naturally from the shortage rather than opposing it. \"However\" also signals contrast, which the cause-and-effect logic does not support. \"Similarly\" signals likeness between two parallel ideas, but the two sentences are linked by cause and effect, not resemblance." },
  { id: "t18rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit includes everything a beginner needs ______ brushes, paints, and a folding easel.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needs, ", "needs: ", "needs; ", "needs "], correct: 1, explanation: "The answer is \"needs: \". Rule: a colon may follow an independent clause to introduce a list, and \"everything a beginner needs\" is a complete clause that the list of brushes, paints, and easel explains. \"needs, \" uses a comma, which is too weak to introduce a defining list this way and reads as a run-on. \"needs; \" uses a semicolon, which must join two independent clauses, but a list of nouns is not an independent clause. \"needs \" with no punctuation runs the clause and the list together with no signal of the relationship, so only the colon works." },
  { id: "t18rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her field notes were so ______ that another researcher could repeat the entire experiment years later without asking a single question.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "hasty", "incomplete", "illegible"], correct: 0, explanation: "The answer is \"meticulous.\" The clue is that another researcher could \"repeat the entire experiment years later without asking a single question,\" which requires extremely careful, thorough notes, and \"meticulous\" means exactly that. \"Hasty\" means rushed and careless, which would leave gaps that force questions. \"Incomplete\" means missing information, the direct opposite of notes detailed enough to reproduce everything. \"Illegible\" means impossible to read, which would also block any faithful reproduction of the experiment." },
  { id: "t18rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is awarded only to applicants who have completed at least sixty volunteer hours and who major in a science field.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An applicant majoring in history with eighty volunteer hours does not qualify.", "Any applicant with sixty volunteer hours qualifies.", "Science majors automatically receive the award.", "Volunteer hours are not considered."], correct: 0, explanation: "The answer is A. The text says the scholarship goes \"only to applicants who have completed at least sixty volunteer hours and who major in a science field,\" so both conditions are required; a history major fails the science-field requirement no matter how many hours, which A correctly states. B is wrong because meeting only the sixty-hour condition is not enough; the science-major condition must also be met. C is wrong because being a science major alone does not satisfy the volunteer-hours condition, so the award is not automatic. D is wrong because the text names volunteer hours as one of the two requirements, so they clearly are considered." },
  { id: "t18rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum restored the mural's faded colors. ______, it repaired cracks in the plaster beneath the paint.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Additionally", "Otherwise", "Instead"], correct: 1, explanation: "The answer is \"Additionally.\" Repairing cracks in the plaster is a second restoration task placed alongside restoring the faded colors, and \"Additionally\" is the transition that adds one related action to another. \"However\" signals contrast, but the two repairs agree as complementary work rather than opposing each other. \"Otherwise\" means \"if not\" and introduces a consequence of the opposite condition, which does not fit a list of tasks. \"Instead\" signals substitution of one action for another, but the museum did both, not one in place of the other." },
  { id: "t18rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the novel's pacing ______, with chapters that lingered for pages on a single afternoon and then leapt across whole decades.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["uneven", "steady", "predictable", "rushed"], correct: 0, explanation: "The answer is \"uneven.\" The sentence describes chapters that \"lingered for pages on a single afternoon and then leapt across whole decades,\" a wildly variable rhythm that \"uneven\" precisely names. \"Steady\" means consistent and unchanging, the opposite of pacing that swings between lingering and leaping. \"Predictable\" means easily anticipated, which contradicts such erratic shifts. \"Rushed\" describes only the leaping-across-decades half and ignores the chapters that linger for pages, so it does not capture the full contrast." },
  { id: "t18rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Some desert plants open their pores only at night, taking in carbon dioxide in the cool darkness and storing it so they can photosynthesize by day without losing precious water.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["These plants conserve water by gathering carbon dioxide at night.", "These plants cannot photosynthesize at all.", "These plants lose most of their water during the day.", "These plants open their pores only at noon."], correct: 0, explanation: "The answer is A. The text says these desert plants \"open their pores only at night, taking in carbon dioxide in the cool darkness\" so they can photosynthesize by day \"without losing precious water,\" which A restates as conserving water by gathering carbon dioxide at night. B is contradicted because the passage says the plants store the carbon dioxide so they can photosynthesize, so they clearly do photosynthesize. C reverses the point, since the whole strategy exists to avoid losing water during the day. D contradicts the text, which says the plants open their pores at night, not at noon." },
  { id: "t18rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the new practice schedule.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "has been"], correct: 1, explanation: "The answer is \"are.\" Rule: in a \"neither ... nor\" construction the verb agrees with the subject nearer to it, and the nearer subject here is the plural \"players,\" which requires the plural \"are.\" \"is\" is singular present and would fit only if the nearer noun were singular, which \"players\" is not. \"was\" is singular and past, wrong in both number and tense for this present-state sentence. \"has been\" is also singular, so it disagrees with the plural \"players\" that sits closest to the verb." },
  { id: "t18rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first telescope the student built barely focused. ______, the experience taught her enough optics to design a far sharper instrument the next year.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "The answer is \"Still.\" The first telescope \"barely focused,\" yet the experience still taught enough optics to build a sharper one, a concession that \"Still\" (meaning \"even so\") signals. \"For instance\" introduces an example of a general claim, but the second sentence is an outcome, not an illustration. \"Therefore\" marks a result, wrongly implying the poor focus caused the learning rather than the learning happening despite the failure. \"In short\" introduces a summary, but the second sentence adds new information rather than restating the first concisely." },
  { id: "t18rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A bakery tracked sales: it sold 120 loaves on Friday, 200 on Saturday, and 90 on Sunday.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Sunday had the lowest sales of the three days.", "Sunday had the highest sales.", "Friday had the highest sales of the three days.", "Friday and Sunday had identical sales."], correct: 0, explanation: "90 loaves on Sunday is the smallest of the three figures, so Sunday had the lowest sales (choice A). Choice B names Sunday as highest (it is the lowest), C wrongly names Friday over Saturday's 200, and D is false since 120 ≠ 90." },
  { id: "t18rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The town built a footbridge ______ connects the two halves of the riverside park.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The answer is \"that.\" Rule: a relative clause modifying a thing is introduced by the relative pronoun \"that,\" and \"connects the two halves\" describes the \"footbridge,\" so \"that\" is correct. \"What\" is a noun-clause word and cannot introduce a relative clause that modifies an existing noun like \"footbridge.\" \"Where\" refers to a location, but the clause tells what the footbridge does, not where something happens. \"and it\" would join a second independent clause without proper punctuation, creating a run-on rather than a clause modifying \"footbridge.\"" },
  { id: "t18rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Tasting the soup before serving, ______ a pinch more salt seemed necessary to the cook.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["tasting the soup before serving, a pinch more salt seemed necessary to the cook", "the cook tasted the soup before serving and decided a pinch more salt was necessary", "a pinch more salt, tasting the soup, seemed necessary", "necessary was a pinch of salt, tasting the soup before serving"], correct: 1, explanation: "The answer is B. Rule: an introductory participial phrase must modify the noun that immediately follows it, so \"tasting the soup before serving\" needs the cook (the one doing the tasting) right after it, which only B provides. The first choice places \"a pinch more salt\" after the modifier, illogically implying the salt tasted the soup. The third choice inserts \"tasting the soup\" beside \"a pinch more salt,\" again attaching the tasting to the salt rather than the cook. The fourth choice opens with \"necessary was a pinch of salt\" and tacks the tasting phrase onto the salt as well, leaving the modifier dangling, so only B attaches it correctly." },
  { id: "t18rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers propose that short midday naps improve afternoon focus because a brief rest clears built-up adenosine, a chemical that makes people feel drowsy.", prompt: "Which finding, if true, would most strengthen the researchers' claim?", type: "mcq", choices: ["Workers who napped at midday made fewer errors in the afternoon than those who did not.", "Most workers prefer coffee to naps.", "Adenosine levels rise during exercise.", "Naps longer than two hours are common."], correct: 0, explanation: "The answer is A. The researchers claim midday naps \"improve afternoon focus,\" and workers who napped making \"fewer errors in the afternoon\" is a direct measurable sign of better focus, so it strengthens the claim. B is about preferring coffee to naps, a matter of preference that says nothing about whether naps improve focus. C notes adenosine rising during exercise, an unrelated fact that does not test napping's effect on afternoon focus. D states that long naps are common, but frequency of long naps does not show that midday naps improve focus, so only A supports the claim." },
  { id: "t18rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The novelist, together with her longtime editors, ______ touring three countries this spring.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The answer is \"is.\" Rule: a phrase introduced by \"together with\" is parenthetical and does not change the number of the subject, so the verb still agrees with the singular \"novelist,\" giving \"is.\" \"are\" is plural and wrongly agrees with \"editors\" inside the \"together with\" phrase rather than with the true subject. \"were\" is plural and past, wrong in both number and tense for this present-tense sentence about a spring tour. \"have been\" is also plural, so it mismatches the singular head noun \"novelist.\"" },
  { id: "t18rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A geologist wants to stress that two separate dating methods produced the same age for the rock. ______, both the radiometric test and the layer count placed it at about ten thousand years.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Notably", "However", "Otherwise"], correct: 1, explanation: "The answer is \"Notably.\" The geologist wants to stress that two methods produced the same age, and the second sentence presents that striking agreement, which \"Notably\" emphasizes. \"By contrast\" signals opposition, but the radiometric test and the layer count agree rather than differ. \"However\" also signals contrast, which misrepresents two methods that point to the same result. \"Otherwise\" means \"if not\" and introduces a consequence of the opposite condition, which does not fit a sentence that confirms the methods' agreement." },
  { id: "t18rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essay's tone is wryly ______: it pokes gentle fun at the very academic conventions it carefully follows.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["self-aware", "earnest", "hostile", "indifferent"], correct: 0, explanation: "The answer is \"self-aware.\" The essay \"pokes gentle fun at the very academic conventions it carefully follows,\" meaning it knowingly comments on its own form, which is exactly what \"self-aware\" describes. \"Earnest\" means sincere and serious, missing the wry, joking quality the sentence stresses. \"Hostile\" means openly antagonistic, which contradicts the gentle, careful fun the essay makes. \"Indifferent\" means unconcerned, but the essay carefully follows and comments on the conventions, the opposite of not caring about them." },
  { id: "t18rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate applies only to buyers who purchase an electric vehicle assembled domestically and who trade in a gas-powered car at the time of purchase.", prompt: "Which buyer clearly qualifies for the rebate?", type: "mcq", choices: ["A buyer of a domestically assembled EV who trades in a gas car.", "A buyer of an imported EV who trades in a gas car.", "A buyer of a domestic EV who keeps their gas car.", "A buyer who purchases another gas car."], correct: 0, explanation: "The answer is A. The text says the rebate applies \"only to buyers who purchase an electric vehicle assembled domestically and who trade in a gas-powered car,\" so both conditions must hold, and only A names a domestically assembled EV plus a gas-car trade-in. B fails the domestic-assembly condition because the EV is imported. C fails the trade-in condition because the buyer keeps the gas car instead of trading it in. D fails the EV condition entirely, since the buyer purchases another gas car rather than an electric vehicle, so only A meets both requirements." },
  { id: "t18rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the lighthouse lens ______ they repainted the railing along the gallery.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["lens, and then", "lens and, then", "lens then", "lens, then"], correct: 0, explanation: "The answer is \"lens, and then.\" Rule: two independent clauses are correctly joined by a comma plus a coordinating conjunction, and \"lens, and then\" places the comma before \"and\" to link \"The crew repaired the lighthouse lens\" with \"they repainted the railing.\" \"lens and, then\" misplaces the comma after \"and,\" breaking the conjunction off from the clause it joins. \"lens then\" omits the conjunction entirely, fusing the two clauses into a run-on. \"lens, then\" uses only a comma, which is a comma splice because \"then\" is an adverb, not a coordinating conjunction, so only the first option joins the clauses correctly." },
  { id: "t18rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although his lectures were famous for their ______ digressions, the professor always returned, eventually, to a single clear thesis.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meandering", "concise", "rigid", "silent"], correct: 0, explanation: "The answer is \"meandering.\" The digressions are set against the professor \"always returned, eventually, to a single clear thesis,\" so they must be wandering and roundabout, which is what \"meandering\" means. \"Concise\" means brief and to the point, the opposite of rambling digressions. \"Rigid\" means stiff and inflexible, which contradicts the loose, wandering quality of digressions. \"Silent\" means without sound, which makes no sense for spoken digressions in a lecture, so only \"meandering\" fits." },
  { id: "t18rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist notes that towns that built public libraries in the 1900s later showed higher rates of small-business formation, crediting the libraries' free access to commercial guides and reading rooms.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Library access to guides and meeting space encouraged new businesses.", "Libraries discouraged people from starting businesses.", "Small businesses funded the libraries directly.", "Library location had no effect on business formation."], correct: 0, explanation: "The answer is A. The economist credits \"the libraries' free access to commercial guides and reading rooms\" for higher rates of small-business formation, which A restates as access to guides and meeting space encouraging new businesses. B reverses the relationship, since the economist says libraries encouraged businesses, not discouraged them. C inverts the funding direction, claiming businesses paid for libraries, which the text never says. D denies any effect, but the economist explicitly ties library access to higher business formation, so only A matches the proposed link." },
  { id: "t18rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The council delayed the vote ______ it still lacked the engineering report on the bridge.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "The answer is \"vote because.\" Rule: when a subordinate clause beginning with \"because\" follows the main clause, no punctuation is needed before it, so \"delayed the vote because it still lacked the report\" is correct. \"vote, because\" inserts an unneeded comma before a trailing \"because\" clause, breaking the tight cause link. \"vote; because\" uses a semicolon, which must join two independent clauses, but \"because it still lacked the report\" is dependent. \"vote: because\" uses a colon, which should introduce a list or explanation set off as its own element, not a subordinate \"because\" clause, so only the unpunctuated option is correct." },
  { id: "t18rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new sorting machine processed twice as many packages per hour. ______, the warehouse cut its overnight shifts in half.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The answer is \"As a result.\" The machine processing twice as many packages is the cause, and the warehouse cutting overnight shifts in half is the effect, a consequence that \"As a result\" signals. \"Nevertheless\" signals concession or contrast, but the shift cut follows naturally from the higher output rather than opposing it. \"For example\" introduces an illustration of a general claim, and the second sentence is an outcome, not an example. \"On the other hand\" signals a contrasting viewpoint, which does not fit a straightforward cause-and-effect link." },
  { id: "t18rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach gave ______ feedback after each drill, naming the exact footwork that needed fixing rather than offering vague praise.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "general", "evasive", "flattering"], correct: 0, explanation: "The answer is \"specific.\" The sentence says the coach named \"the exact footwork that needed fixing rather than offering vague praise,\" so the feedback is precise and detailed, which \"specific\" means. \"General\" means broad and vague, the very thing the sentence contrasts the feedback against. \"Evasive\" means avoiding the point, which contradicts naming the exact footwork to fix. \"Flattering\" means giving excessive praise, but the sentence explicitly rejects vague praise in favor of pointed correction, so only \"specific\" fits." },
  { id: "t18rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A long-term study found that removing a single keystone sea-star species allowed mussels to crowd out other shellfish, which in turn drove away the fish and birds that had fed on the vanished species.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Losing one key species set off a cascade that reshaped the whole community.", "The sea star had no effect on other animals.", "Mussel populations declined after the sea star left.", "Fish and birds increased once the sea star was removed."], correct: 0, explanation: "The answer is A. The text says removing the keystone sea star \"allowed mussels to crowd out other shellfish, which in turn drove away the fish and birds,\" a chain of effects that A captures as one loss setting off a cascade that reshaped the community. B is contradicted because the removal clearly had large effects on mussels, shellfish, fish, and birds. C reverses the text, which says mussels crowded out other shellfish, so mussels increased rather than declined. D contradicts the passage, which says fish and birds were driven away, not increased, after the sea star was removed." },
];

// ─────────────────────── PRACTICE TEST 18 · R&W M2 easy (27) ─────────────────
const T18_RW_M2E: SatQuestion[] = [
  { id: "t18rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The juice was too ______, so I added a little water to make it less strong.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sweet", "quiet", "tall", "early"], correct: 0, explanation: "The answer is \"sweet.\" The clue is that water is added \"to make it less strong,\" so the missing word must name a taste that water can dilute, and an overly \"sweet\" juice is exactly that. \"Quiet\" describes sound, not flavor, so water could not lessen it. \"Tall\" describes height and has nothing to do with taste. \"Early\" describes time and likewise cannot be diluted by water, so only \"sweet\" fits the sentence logic." },
  { id: "t18rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three birds ______ singing in the tall oak tree.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" Rule: a verb must agree in number with its subject, and the subject \"three birds\" is plural, so it requires the plural verb \"are.\" \"Is\" is the singular present form and cannot agree with a plural subject. \"Was\" is singular past and is wrong in both number and tense for the ongoing action \"singing.\" \"Am\" agrees only with the first-person \"I,\" never with \"birds,\" so it is impossible here." },
  { id: "t18rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bees visit many flowers to collect nectar, and as they move, they spread pollen that helps the flowers make seeds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees help flowers reproduce while collecting nectar.", "Bees never touch flowers.", "Flowers make nectar from seeds.", "Bees prevent flowers from making seeds."], correct: 0, explanation: "The answer is A. The text says that as bees collect nectar they \"spread pollen that helps the flowers make seeds,\" which is exactly reproduction aided during nectar-gathering. B is contradicted because the passage states bees \"visit many flowers,\" so they clearly touch them. C reverses the relationship: the text says flowers make seeds with pollen's help, not that nectar comes from seeds. D contradicts the passage outright, since bees help, not prevent, seed-making." },
  { id: "t18rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The movie was about to start. ______, we hurried to find our seats.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is \"So.\" The first sentence gives a cause (the movie was about to start) and the second gives the effect (we hurried to our seats), and \"So\" is the transition that signals that result relationship. \"For example\" would introduce an illustration of a general point, but no general claim is being illustrated. \"However\" signals contrast, yet hurrying agrees with, rather than opposes, the movie starting. \"Meanwhile\" marks two simultaneous events, but here one event clearly causes the other." },
  { id: "t18rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at a small restaurant near the river.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "The answer is \"ate.\" Rule: the time marker \"last night\" places the action in the completed past, which requires the simple past tense \"ate.\" \"Eat\" is present tense and clashes with a past time marker. \"Eats\" is the third-person singular present and is wrong in both tense and (for \"we\") number. \"Eating\" is a present participle that cannot stand alone as the main verb without a helping verb like \"were,\" so it leaves the sentence without a finite verb." },
  { id: "t18rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puppy was very ______ and ran in circles around the yard for an hour.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["energetic", "sleepy", "still", "quiet"], correct: 0, explanation: "The answer is \"energetic.\" The puppy \"ran in circles around the yard for an hour,\" which is sustained vigorous activity, and \"energetic\" precisely names that quality. \"Sleepy\" describes a drowsy, low-energy state and contradicts an hour of running. \"Still\" means motionless, the direct opposite of running in circles. \"Quiet\" describes a lack of noise and does not explain the constant movement the sentence stresses." },
  { id: "t18rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives you exercise, and produces no pollution.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is expensive.", "Walking to school causes pollution.", "Walking to school is unhealthy."], correct: 0, explanation: "The answer is A. The text lists three advantages of walking to school: it \"saves money,\" \"gives you exercise,\" and \"produces no pollution,\" so \"several benefits\" accurately summarizes them. B is contradicted because saving money is the opposite of being expensive. C is contradicted because the text says walking \"produces no pollution.\" D is contradicted because providing exercise makes walking healthy, not unhealthy, so only A fits the whole list." },
  { id: "t18rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She read for ______ hour before going to sleep.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is \"an.\" Rule: the article \"a\" or \"an\" is chosen by the following sound, not the spelling, and \"hour\" begins with a silent h so it starts with the vowel sound \"ow,\" requiring \"an.\" \"A\" is used only before a consonant sound and would be wrong before that vowel sound. \"The only\" wrongly implies there was a single specific hour rather than an unspecified one. \"Some\" suggests an unspecified amount and does not fit the singular count noun \"hour\" preceded by a number-of-units idea." },
  { id: "t18rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The map was so ______ that we found the trail without any trouble.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "torn", "blank"], correct: 0, explanation: "The answer is \"clear.\" The result clause says \"we found the trail without any trouble,\" so the map must have been easy to read, which is what \"clear\" means. \"Confusing\" describes a map that would cause trouble, the opposite of the result. \"Torn\" describes physical damage that would hinder, not help, navigation. \"Blank\" describes a map with no information, which could not guide anyone to the trail at all." },
  { id: "t18rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ planning a trip to the mountains.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" Rule: a compound subject joined by \"and\" is plural and takes a plural verb, and \"my sister and I\" names two people, so it requires \"are.\" \"Is\" is singular present and cannot agree with two subjects. \"Was\" is singular past and is wrong in both number and tense for the ongoing \"planning.\" \"Am\" agrees only with a lone \"I,\" never with a compound subject, so it cannot be used here." },
  { id: "t18rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Owls have special feathers that let them fly almost silently, helping them surprise the small animals they hunt at night.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Owls' silent flight helps them hunt.", "Owls cannot fly at all.", "Owls hunt only during the day.", "Owls' feathers make loud noises."], correct: 0, explanation: "The answer is A. The text says owls' special feathers let them \"fly almost silently, helping them surprise the small animals they hunt,\" directly linking silent flight to hunting. B is contradicted because the passage describes owls flying, so they clearly can fly. C is contradicted because the text says they hunt \"at night,\" not during the day. D reverses the passage, which says the feathers make owls quiet, not loud, so only A matches the text." },
  { id: "t18rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Heavy rain flooded the road. ______, the bus had to take a longer route.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The answer is \"As a result.\" The first sentence is a cause (rain flooded the road) and the second is its effect (the bus took a longer route), and \"As a result\" is the transition that signals that consequence. \"However\" marks a contrast, but the longer route agrees with, rather than opposes, the flooding. \"For example\" introduces an illustration of a general claim, and none is being illustrated here. \"Instead\" signals a substitution of one option for another, but the sentence shows cause and effect, not a swap." },
  { id: "t18rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the class ______ a documentary about volcanoes.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["watch", "watches", "watched", "watching"], correct: 2, explanation: "The answer is \"watched.\" Rule: the time marker \"yesterday\" places the action in the completed past, which requires the simple past tense \"watched.\" \"Watch\" is the base present form and clashes with a past time marker. \"Watches\" is third-person singular present and is wrong in tense even though the collective \"class\" is singular. \"Watching\" is a present participle that needs a helping verb like \"was\" and cannot serve alone as the main verb, leaving the clause incomplete." },
  { id: "t18rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "The answer is \"tired.\" The campers \"fell asleep quickly\" after \"the long hike,\" and \"tired\" is the state that explains falling asleep fast. \"Excited\" describes heightened energy, which would tend to keep someone awake rather than asleep. \"Hungry\" describes a need for food and does not account for quickly falling asleep. \"Curious\" describes eagerness to learn and has no connection to sleepiness, so only \"tired\" fits the result." },
  { id: "t18rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from 7 a.m. to 8 p.m. on weekdays but is closed on Mondays for cleaning.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot swim at the pool on Monday.", "The pool is open at midnight.", "The pool never closes.", "The pool opens at 8 p.m."], correct: 0, explanation: "The answer is A. The text states the pool \"is closed on Mondays for cleaning,\" so you cannot swim there on Monday. B is contradicted because the hours are 7 a.m. to 8 p.m., so the pool is not open at midnight. C is contradicted because the text describes both daily closing at 8 p.m. and a full Monday closure. D misreads the hours: 8 p.m. is the closing time, not the opening time, so only A is supported." },
  { id: "t18rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat curled up in ______ favorite spot by the window.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The answer is \"its.\" Rule: a possessive determiner must agree with its antecedent, and the singular \"cat\" needs the singular possessive \"its.\" \"It's\" is the contraction of \"it is\" and would wrongly read \"in it is favorite spot,\" which is ungrammatical. \"Their\" is a plural possessive and cannot refer to a single cat. \"They're\" is the contraction of \"they are,\" a subject-plus-verb that cannot show possession at all, so only \"its\" works." },
  { id: "t18rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Many animals migrate to find food. ______, geese fly south each fall to reach warmer feeding grounds.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is \"For example.\" The first sentence makes a general claim (many animals migrate to find food) and the second gives a specific case (geese flying south to reach feeding grounds), so the illustrative \"For example\" fits. \"However\" signals contrast, but the geese support rather than oppose the general claim. \"Instead\" marks a substitution, yet the second sentence supplies an example, not a replacement. \"Otherwise\" means \"if not,\" introducing a consequence of the opposite condition, which does not match an illustration." },
  { id: "t18rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The box was too ______ to lift, so we used a cart to move it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "small", "soft"], correct: 0, explanation: "The answer is \"heavy.\" The sentence says the box was \"too ____ to lift, so we used a cart,\" and needing a cart because you cannot lift something points to it being too \"heavy.\" \"Light\" describes a box easy to lift, the opposite of needing a cart. \"Small\" describes size, and a small box would be easier, not harder, to lift by hand. \"Soft\" describes texture and gives no reason a cart would be required, so only \"heavy\" fits." },
  { id: "t18rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The shelves ______ filled with books of every color.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" Rule: a verb agrees in number with its subject, and \"shelves\" is the plural of \"shelf,\" so it takes the plural verb \"are.\" \"Is\" is singular present and cannot agree with a plural subject. \"Was\" is singular past and is wrong in both number and tense for the present-state description \"filled with books.\" \"Am\" agrees only with the first-person \"I\" and never with \"shelves,\" so it is impossible here." },
  { id: "t18rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Ice floats on water because frozen water is less dense than liquid water, which is unusual for most substances.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Ice floats because it is less dense than liquid water.", "Ice always sinks in water.", "Ice is denser than liquid water.", "Water cannot freeze."], correct: 0, explanation: "The answer is A. The text states ice floats \"because frozen water is less dense than liquid water,\" which is exactly what A restates. B is contradicted because the passage says ice floats, not sinks. C reverses the stated fact: frozen water is less dense, not denser, than liquid water. D contradicts the text, which describes water that has frozen into ice, so freezing clearly happens; only A matches the given reason." },
  { id: "t18rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to picnic in the park. ______, a sudden storm sent us home early.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The answer is \"However.\" The plan to picnic is interrupted by an unexpected storm, an opposition between intention and outcome that \"However\" signals. \"Therefore\" marks a result, but the storm thwarts the plan rather than following from it. \"For example\" introduces an illustration, and the storm is not an example of picnicking. \"Similarly\" signals likeness, yet the storm contrasts with the plan instead of resembling it, so only \"However\" fits." },
  { id: "t18rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month the band ______ to perform at the city festival.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The answer is \"plans.\" Rule: a singular collective noun like \"band\" takes a singular verb, and the third-person singular present \"plans\" fits a scheduled future cued by \"next month.\" \"Plan\" is the plural/base present form and does not agree with the singular \"band.\" \"Planned\" is past tense and wrongly places a next-month event in the past. \"Planning\" is a participle that needs a helping verb such as \"is\" and cannot stand alone as the main verb, so only \"plans\" works." },
  { id: "t18rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new laptop is very ______; it starts up in just a few seconds.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["fast", "slow", "loud", "wide"], correct: 0, explanation: "The answer is \"fast.\" The clause \"it starts up in just a few seconds\" describes quick performance, which is what \"fast\" means. \"Slow\" is the direct opposite and contradicts a few-second startup. \"Loud\" describes sound level, not speed, so it does not match the startup-time evidence. \"Wide\" describes physical width and has nothing to do with how quickly the laptop starts, so only \"fast\" fits." },
  { id: "t18rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Planting trees in cities provides shade, cleans the air, and gives birds a place to nest.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["City trees offer several benefits.", "City trees harm the air.", "City trees provide no shade.", "City trees keep birds away."], correct: 0, explanation: "The answer is A. The text lists three advantages of city trees: they \"provide shade,\" \"clean the air,\" and \"give birds a place to nest,\" which \"several benefits\" sums up. B is contradicted because cleaning the air is the opposite of harming it. C is contradicted because the text says trees provide shade. D is contradicted because the text says trees give birds a place to nest, the opposite of keeping them away, so only A fits the list." },
  { id: "t18rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He grabbed ______ apple from the bowl on his way out.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is \"an.\" Rule: the choice between \"a\" and \"an\" depends on the following sound, and \"apple\" begins with the vowel sound \"a,\" so it takes \"an.\" \"A\" is used only before a consonant sound and would be wrong before a vowel sound. \"The only\" wrongly implies a single specific apple rather than one unspecified apple from the bowl. \"Some\" suggests an unspecified quantity and does not fit grabbing a single countable apple, so only \"an\" works." },
  { id: "t18rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were easy to follow. ______, the desk took less than an hour to assemble.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "However", "Instead", "Otherwise"], correct: 0, explanation: "The answer is \"As a result.\" The first sentence is a cause (the directions were easy) and the second is its effect (the desk assembled in under an hour), so the consequence transition \"As a result\" fits. \"However\" marks contrast, but quick assembly agrees with easy directions rather than opposing them. \"Instead\" signals a substitution that the sentence does not contain. \"Otherwise\" means \"if not,\" introducing the consequence of the opposite condition, which does not match a straightforward cause and effect." },
  { id: "t18rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "The answer is \"amazed.\" Making a rabbit disappear is a surprising feat, and \"amazed\" is the reaction such a trick produces in an audience. \"Bored\" describes disinterest, which contradicts watching a striking illusion. \"Sleepy\" describes drowsiness and does not match a moment of surprise. \"Angry\" describes hostility, an emotion a magic trick would not normally provoke, so only \"amazed\" fits the situation." },
];

// ─────────────────────── PRACTICE TEST 18 · R&W M2 hard (27) ─────────────────
const T18_RW_M2H: SatQuestion[] = [
  { id: "t18rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic's praise was so ______ that readers could not tell whether she admired the film or merely tolerated it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["tepid", "fervent", "scathing", "lavish"], correct: 0, explanation: "The answer is \"tepid.\" Readers \"could not tell whether she admired the film or merely tolerated it,\" so the praise was lukewarm and noncommittal, which is exactly what \"tepid\" means. \"Fervent\" means intensely enthusiastic, which would make her admiration obvious rather than uncertain. \"Scathing\" means harshly critical, but the sentence describes praise, not an attack. \"Lavish\" means generous and abundant, which would also signal clear admiration rather than the faint, hard-to-read tone the sentence requires." },
  { id: "t18rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The chapter opens by stating a familiar proverb, then spends its remaining pages assembling counterexamples that quietly dismantle it.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It presents a common belief and then undermines it with counterexamples.", "It proves the proverb true with evidence.", "It lists proverbs without comment.", "It repeats the same proverb throughout."], correct: 0, explanation: "The answer is A. The text says the chapter \"opens by stating a familiar proverb, then spends its remaining pages assembling counterexamples that quietly dismantle it,\" a present-then-undermine structure. B is wrong because the counterexamples dismantle the proverb rather than prove it true. C is wrong because only one proverb is named, and it is examined, not merely listed without comment. D is wrong because the chapter moves on to counterexamples rather than repeating the same proverb throughout." },
  { id: "t18rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 95% of its rated output in year 1, 90% in year 5, and 60% in year 20.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined faster per year between years 5 and 20 than between years 1 and 5.", "Output increased over time.", "Output stayed exactly constant.", "The panel produced nothing by year 5."], correct: 0, explanation: "From year 1 to 5 output fell 5 points over 4 years (about 1.25 points per year); from year 5 to 20 it fell 30 points over 15 years (2 points per year), a faster per-year decline (choice A). Choices B and C contradict the falling figures, and D is false since output was still 90% at year 5." },
  { id: "t18rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The drug shrank tumors in early trials. ______, it caused liver damage severe enough to halt the study.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The answer is \"However.\" A promising result (the drug shrank tumors) is set against a serious harm (liver damage that halted the study), an opposition that \"However\" signals. \"Therefore\" marks a result, wrongly implying the tumor shrinkage caused the liver damage. \"Likewise\" signals similarity, but a benefit and a harm are contrasting, not alike. \"Accordingly\" also marks a consequence, again falsely casting the harm as a result of the benefit rather than an opposing outcome." },
  { id: "t18rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "The answer is \"to present.\" Rule: items in a series must be parallel in form, and the list already uses the infinitives \"to analyze\" and \"to write,\" so the third item must also be an infinitive, \"to present.\" \"presenting\" is a gerund, which breaks the infinitive pattern of the series. \"present\" is a bare verb form that does not match the \"to + verb\" structure of the other items. \"presented\" is a past-tense or participle form that likewise fails to parallel \"to analyze\" and \"to write,\" so only \"to present\" keeps the series consistent." },
  { id: "t18rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its narrator, dwelling on his cowardice as openly as his rare moments of courage.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["flatter", "condemn", "introduce", "ignore"], correct: 0, explanation: "The answer is \"flatter.\" The memoir dwells \"on his cowardice as openly as his rare moments of courage,\" showing the narrator honestly rather than glossing over his faults, so it refuses to \"flatter\" him. \"Condemn\" means to harshly denounce, but the memoir treats cowardice and courage evenhandedly rather than attacking him. \"Introduce\" means to present for the first time, which does not fit the contrast between honesty and praise the sentence draws. \"Ignore\" means to overlook, the opposite of dwelling openly on his cowardice, so only \"flatter\" fits the refusal to whitewash him." },
  { id: "t18rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats the plague as a purely medical catastrophe, the recent study frames it as a social rupture that reshaped labor, wages, and class.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast a medical view of the plague with a newer social interpretation.", "To prove the plague had no social effects.", "To summarize only the traditional account.", "To deny that the plague occurred."], correct: 0, explanation: "The answer is A. The \"Where the traditional account treats … the recent study frames …\" framing sets a medical view against a newer social interpretation, a contrast of two readings. B is wrong because the text endorses the social reading rather than proving the plague had no social effects. C is wrong because the passage presents both the traditional and the recent account, not only the traditional one. D is wrong because nothing in the text denies the plague occurred; it debates how to interpret it." },
  { id: "t18rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day crew finished the inventory ahead of schedule ______ the night crew fell two hours behind on the same task.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["schedule, the", "schedule; the", "schedule the", "schedule: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone creates a splice, no punctuation creates a run-on, and a colon does not fit two contrasting clauses." },
  { id: "t18rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the committee's report is riddled with qualifications that hedge every recommendation it makes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["decisive", "cautious", "tentative", "evasive"], correct: 0, explanation: "The answer is \"decisive.\" The phrase \"Far from being ____\" demands a word opposite to how the report is described, and a report \"riddled with qualifications that hedge every recommendation\" is the opposite of \"decisive,\" so the report is far from decisive. \"Cautious\" describes the hedging itself, so the report would be cautious, not far from it. \"Tentative\" likewise names the hesitant quality the qualifications create, matching rather than contradicting the report. \"Evasive\" also describes the report's noncommittal hedging, so plugging it into \"far from\" would reverse the intended meaning; only \"decisive\" supplies the needed contrast." },
  { id: "t18rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the merger will lower prices for consumers. Yet in the two years after a nearly identical merger in another market, prices there rose by 8%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that casts doubt on the supporters' claim.", "It restates the supporters' claim exactly.", "It confirms that prices always fall after mergers.", "It proposes a different merger."], correct: 0, explanation: "The answer is A. The second sentence reports that after \"a nearly identical merger,\" prices \"rose by 8%,\" evidence that works against the supporters' claim that this merger will lower prices. B is wrong because the sentence introduces contrary evidence rather than restating the supporters' claim. C is wrong because the example shows prices rising, the opposite of always falling after mergers. D is wrong because the sentence cites a past comparable merger as evidence, not a new merger proposal." },
  { id: "t18rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The recipe rests on three essentials ______ fresh tomatoes, good olive oil, and a generous pinch of salt.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials,", "essentials:", "essentials;", "essentials"], correct: 1, explanation: "The answer is \"essentials:\". Rule: a colon follows an independent clause to introduce a list, and \"The recipe rests on three essentials\" is a complete clause that the items tomatoes, olive oil, and salt explain. \"essentials,\" uses a comma, which is too weak to introduce this defining list and reads as a run-on. \"essentials;\" uses a semicolon, which must join two independent clauses, but the list of ingredients is not an independent clause. \"essentials\" with no punctuation fuses the clause and the list together with no signal, so only the colon properly introduces the list." },
  { id: "t18rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorted the clear images with near-perfect accuracy. ______, it stumbled badly on photos taken in dim light.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "The answer is \"Nonetheless.\" A success on clear images is followed by a failure on dim ones, a contrast between strong and weak performance that \"Nonetheless\" (meaning \"in spite of that\") signals. \"Indeed\" intensifies or confirms a prior point, but the second sentence opposes the first rather than reinforcing it. \"Therefore\" marks a result, wrongly implying the near-perfect accuracy caused the failure on dim photos. \"Likewise\" signals similarity, but the two results differ sharply, so only \"Nonetheless\" captures the contrast." },
  { id: "t18rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, students who used the new study app scored 15% higher on recall tests but reported 25% more screen fatigue than students who studied on paper.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The app improved recall scores but increased reported fatigue.", "The app improved both recall and reduced fatigue.", "The app had no measurable effect.", "Paper users scored higher on recall."], correct: 0, explanation: "The answer is A. The text reports that app users \"scored 15% higher on recall tests but reported 25% more screen fatigue,\" so the app raised recall and raised fatigue. B is wrong because fatigue increased rather than decreased. C is wrong because there were two clear measured effects, not no measurable effect. D is wrong because the app users, not the paper users, scored higher on recall, so only A states both outcomes correctly." },
  { id: "t18rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The statue that stands among the older monuments ______ to a sculptor whose later works fill the museum's main hall.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The answer is \"belongs.\" Rule: a verb agrees with its subject, not with a noun inside an intervening modifier, and the subject is the singular \"statue,\" not the plural \"monuments\" in the relative clause. \"Belong\" is the plural present form and wrongly agrees with \"monuments\" rather than \"statue.\" \"Belonging\" is a participle that cannot serve as the sentence's main finite verb without a helping verb. \"To belong\" is an infinitive, which also cannot function as the finite main verb the clause needs, so only \"belongs\" works." },
  { id: "t18rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The architect was admired for her ______ — for stripping each design down to the few elements a building truly needed.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["austerity", "extravagance", "indecision", "nostalgia"], correct: 0, explanation: "The answer is \"austerity.\" The architect is admired \"for stripping each design down to the few elements a building truly needed,\" a spare, severe simplicity that \"austerity\" names. \"Extravagance\" means lavish excess, the direct opposite of stripping a design down to essentials. \"Indecision\" means an inability to choose, but deliberately paring a design down is a decisive act, not a wavering one. \"Nostalgia\" means longing for the past, which has nothing to do with minimal, pared-down design, so only \"austerity\" fits." },
  { id: "t18rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that early vaccines were crude and sometimes dangerous, then argues that the very crudeness of those efforts taught the methods that made modern vaccines remarkably safe.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an early weakness as the source of a later strength.", "It denies that early vaccines had any flaws.", "It claims vaccines never improved.", "It lists vaccine prices over time."], correct: 0, explanation: "The answer is A. The author concedes early vaccines \"were crude and sometimes dangerous,\" then argues \"the very crudeness of those efforts taught the methods\" behind modern safety, recasting an early weakness as a later strength. B is wrong because the author admits the early flaws rather than denying them. C is wrong because the text says modern vaccines became \"remarkably safe,\" so vaccines clearly improved. D is wrong because the passage discusses safety and method, not vaccine prices over time." },
  { id: "t18rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed for months in a small studio ______ the orchestra found the concert hall's vast acoustics startling at first.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the concert hall's vast acoustics startled the orchestra", "the orchestra found the concert hall's vast acoustics startling at first", "startling were the hall's acoustics, rehearsing for months", "it was startling, the vast acoustics of the hall"], correct: 1, explanation: "The answer is B. Rule: an introductory participial phrase must modify the noun that immediately follows it, so \"having rehearsed for months\" needs the orchestra (the thing that rehearsed) right after the blank, which only B provides. A places \"the concert hall's vast acoustics\" after the modifier, illogically saying the acoustics rehearsed for months. C puts \"startling\" first and tacks \"rehearsing for months\" onto the acoustics, again misattaching the rehearsal. D opens with \"it,\" which cannot be the thing that rehearsed and leaves the modifier dangling, so only B attaches the phrase correctly." },
  { id: "t18rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "A linguist wants to underscore that an obscure dialect preserves a sound the standard language lost centuries ago. ______, the dialect retains a hard consonant that vanished from the mainstream tongue by the 1400s.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In contrast", "Specifically", "Nevertheless", "Otherwise"], correct: 1, explanation: "The answer is \"Specifically.\" The first sentence makes a general claim that the dialect preserves a lost sound, and the second names the precise case (a hard consonant gone from the mainstream by the 1400s), an illustration that \"Specifically\" signals. \"In contrast\" signals opposition, but the second sentence supports rather than opposes the first. \"Nevertheless\" signals concession, yet the example agrees with the general claim instead of qualifying it. \"Otherwise\" means \"if not\" and introduces the consequence of the opposite condition, which does not fit a sentence that gives a supporting detail." },
  { id: "t18rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The negotiator's ______ — her refusal to be rushed or rattled — let her wait out opponents who grew impatient and conceded.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["composure", "volatility", "haste", "timidity"], correct: 0, explanation: "The answer is \"composure.\" The dash defines the trait as \"her refusal to be rushed or rattled,\" which is calm self-control, exactly what \"composure\" means. \"Volatility\" means a tendency to erupt or change suddenly, the opposite of refusing to be rattled. \"Haste\" means hurried action, which contradicts refusing to be rushed. \"Timidity\" means fearfulness, but a timid negotiator could not patiently wait out impatient opponents until they conceded, so only \"composure\" fits the calm steadiness described." },
  { id: "t18rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The historian argues that the canal's true significance lay not in the goods it carried but in the towns that sprang up along its banks, each becoming a hub of trade and migration.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The canal mattered most for the trading towns it created along its route.", "The canal carried no goods at all.", "The canal's only value was the cargo it moved.", "The towns existed long before the canal."], correct: 0, explanation: "The answer is A. The historian says the canal's \"true significance lay not in the goods it carried but in the towns that sprang up along its banks,\" each becoming a hub of trade, which A restates. B is wrong because the text says the canal did carry goods; it simply was not where its significance lay. C is wrong because it claims the cargo was the only value, the very view the historian rejects. D is wrong because the towns \"sprang up\" because of the canal, so they did not predate it." },
  { id: "t18rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The grant supports projects in three regions ______ the northern highlands, the central plains, and the southern coast.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["regions,", "regions:", "regions;", "regions"], correct: 1, explanation: "The answer is \"regions:\". Rule: a colon follows an independent clause to introduce a list, and \"The grant supports projects in three regions\" is a complete clause that the named highlands, plains, and coast specify. \"regions,\" uses a comma, which is too weak to introduce this defining list and reads as a run-on. \"regions;\" uses a semicolon, which must join two independent clauses, but the list of place names is not an independent clause. \"regions\" with no punctuation runs the clause and the list together with no signal, so only the colon introduces the list correctly." },
  { id: "t18rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The lecture was anything but ______: the speaker layered jokes, anecdotes, and surprising tangents until the hour flew by.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dull", "lively", "engaging", "amusing"], correct: 0, explanation: "The answer is \"dull.\" The phrase \"anything but ____\" demands a word that is the opposite of how the lecture is described, and a lecture layered with \"jokes, anecdotes, and surprising tangents until the hour flew by\" is the opposite of \"dull.\" \"Lively\" describes the energetic quality the lecture actually has, so \"anything but lively\" would contradict the evidence. \"Engaging\" likewise matches the lecture's appeal rather than negating it. \"Amusing\" again names a trait the lecture clearly possesses, so plugging it in would reverse the intended meaning; only \"dull\" creates the needed contrast." },
  { id: "t18rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study reported that a fishing ban let cod populations recover 40% over a decade, but lobster catches in the same waters fell 15% as the recovering cod preyed on young lobsters.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The ban helped cod recover while reducing lobster catches.", "The ban harmed cod populations.", "Lobster catches rose after the ban.", "The ban had no effect on either species."], correct: 0, explanation: "The answer is A. The text says the ban \"let cod populations recover 40%\" while \"lobster catches … fell 15%\" as recovering cod preyed on young lobsters, so the ban helped cod and reduced lobster catches. B is wrong because cod recovered, not declined, under the ban. C is wrong because lobster catches fell rather than rose. D is wrong because the ban clearly affected both species, so only A captures both reported effects." },
  { id: "t18rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The proposal, which had been revised by every department and approved by the board, ______ now ready for a public vote.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["are", "were", "is", "have been"], correct: 2, explanation: "The answer is \"is.\" Rule: a verb agrees with its subject, not with nouns inside intervening clauses, and the singular subject \"proposal\" takes the singular \"is\" even after the long \"which had been revised ... and approved\" clause. \"are\" is plural and wrongly agrees with the nearby plural nouns \"departments\" or \"board members\" rather than \"proposal.\" \"were\" is plural and past, wrong in both number and tense for a proposal that \"now\" is ready. \"have been\" is also plural, so it disagrees with the singular subject \"proposal,\" leaving \"is\" as the only correct choice." },
  { id: "t18rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The first prototype overheated within minutes. ______, its failure revealed exactly which component the engineers needed to redesign.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Yet", "Therefore", "Likewise", "Meanwhile"], correct: 0, explanation: "The answer is \"Yet.\" The prototype overheated (a failure), but that failure still revealed which component to redesign (a benefit), a concession that \"Yet\" signals. \"Therefore\" marks a result, wrongly casting the overheating as a planned cause of the insight rather than a setback that nonetheless proved useful. \"Likewise\" signals similarity, but a failure and a useful insight are contrasting, not alike. \"Meanwhile\" marks two simultaneous events, yet here one event yields the other rather than merely happening at the same time, so only \"Yet\" fits." },
  { id: "t18rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The poet's imagery is strikingly ______: a single line can evoke a smell, a sound, and a color all at once.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sensory", "abstract", "plain", "muted"], correct: 0, explanation: "The answer is \"sensory.\" The imagery can \"evoke a smell, a sound, and a color all at once,\" appealing directly to the senses, which is exactly what \"sensory\" means. \"Abstract\" means dealing with ideas rather than concrete perceptions, the opposite of imagery rooted in smell, sound, and color. \"Plain\" means unremarkable and simple, which contradicts the striking, vivid quality the sentence stresses. \"Muted\" means subdued or faint, but the imagery is described as strikingly rich across multiple senses, so only \"sensory\" fits." },
  { id: "t18rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The economist notes that when a city replaced its flat bus fare with a distance-based one, ridership in outer neighborhoods dropped sharply, suggesting the new fares discouraged the longest, most essential trips.", prompt: "Which choice best describes the economist's reasoning?", type: "mcq", choices: ["The fare change reduced ridership on the trips it made most expensive.", "The fare change increased outer-neighborhood ridership.", "Distance had no effect on ridership.", "Flat fares discouraged short trips."], correct: 0, explanation: "The answer is A. The economist notes that after a flat fare became distance-based, \"ridership in outer neighborhoods dropped sharply,\" suggesting the new fares discouraged the longest, most expensive trips. B is wrong because outer-neighborhood ridership dropped, not increased. C is wrong because the drop was tied directly to distance-based pricing, so distance clearly mattered. D is wrong because the passage faults the new distance-based fares for long trips, not flat fares for short ones, so only A matches the reasoning." },
];

// ─────────────────────── PRACTICE TEST 18 · MATH M1 (22) ─────────────────────
const T18_MATH_M1: SatQuestion[] = [
  { id: "t18m1-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 5x − 3 = 22, what is the value of x?", type: "mcq", choices: ["3", "4", "5", "6"], correct: 2, explanation: "Goal: solve for x. Add 3 to both sides: 5x = 25. Divide by 5: x = 5. The trap is stopping at 5x = 25 and reading 25, or forgetting to add 3 first." },
  { id: "t18m1-2", section: "math", domain: "Algebra", difficulty: "easy", prompt: "A taxi charges a $4 base fee plus $2 per mile. Which equation gives the total cost C for m miles?", type: "mcq", choices: ["C = 4m + 2", "C = 2m + 4", "C = 6m", "C = 2m − 4"], correct: 1, explanation: "Goal: model fixed plus per-mile cost. The $4 base is constant and the $2 applies to each mile, giving C = 2m + 4. Choice A swaps the coefficients, putting the per-mile rate on the constant." },
  { id: "t18m1-3", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A shirt originally priced at $40 is on sale for 25% off. What is the sale price?", type: "mcq", choices: ["$10", "$25", "$30", "$32"], correct: 2, explanation: "Goal: apply a 25% discount. 25% of $40 is 0.25 × 40 = $10 off, so the sale price is 40 − 10 = $30. The trap is reporting the $10 discount itself instead of the remaining price." },
  { id: "t18m1-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "Line ℓ passes through the points (0, 1) and (2, 7). What is the slope of line ℓ?", type: "mcq", choices: ["2", "3", "4", "6"], correct: 1, explanation: "Goal: find slope from two points. Slope = (7 − 1)/(2 − 0) = 6/2 = 3. The trap is using the rise of 6 alone (choice D) without dividing by the run of 2." },
  { id: "t18m1-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x² + 2x, what is f(3)?", type: "mcq", choices: ["9", "11", "15", "18"], correct: 2, explanation: "Goal: evaluate the function at x = 3. f(3) = 3² + 2(3) = 9 + 6 = 15. The trap is computing only 3² = 9 and forgetting the 2x term." },
  { id: "t18m1-6", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has length 9 and width 4. What is its area?", type: "mcq", choices: ["13", "26", "36", "40"], correct: 2, explanation: "Goal: find rectangle area. Area = length × width = 9 × 4 = 36. The trap is computing the perimeter 2(9 + 4) = 26 (choice B) instead of the area." },
  { id: "t18m1-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The ratio of cats to dogs at a shelter is 3 to 5. If there are 24 cats, how many dogs are there?", type: "mcq", choices: ["8", "30", "40", "45"], correct: 2, explanation: "Goal: scale a ratio. The 3 in the ratio corresponds to 24 cats, so each ratio unit is 24/3 = 8 animals. Dogs = 5 × 8 = 40. The trap is multiplying 24 by 5/3 incorrectly or using 30." },
  { id: "t18m1-8", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3(x + 2) = 2x + 11, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve the linear equation. Distribute: 3x + 6 = 2x + 11. Subtract 2x: x + 6 = 11. Subtract 6: x = 5. The trap is failing to distribute the 3 across both terms in the parentheses." },
  { id: "t18m1-9", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["3", "5", "7", "10"], correct: 2, explanation: "Goal: find the sum of roots. Factoring gives (x − 2)(x − 5) = 0, so the roots are 2 and 5 and their sum is 7. Alternatively, for ax² + bx + c the sum of roots is −b/a = 7. The trap is reporting the product 10 instead of the sum." },
  { id: "t18m1-10", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A data set is 4, 8, 8, 10, 20. What is the median?", type: "mcq", choices: ["8", "10", "12", "20"], correct: 0, explanation: "Goal: find the median. The five values are already in order, so the middle value (the third) is 8. The trap is computing the mean (50/5 = 10) instead of the middle value." },
  { id: "t18m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A line is given by 2x + 3y = 12. What is its y-intercept?", type: "mcq", choices: ["2", "3", "4", "6"], correct: 2, explanation: "Goal: find the y-intercept. Set x = 0: 3y = 12, so y = 4; the y-intercept is (0, 4). The trap is setting y = 0 instead, which gives the x-intercept x = 6 (choice D)." },
  { id: "t18m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If 2^x = 32, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve the exponential equation. Write 32 as a power of 2: 32 = 2^5, so 2^x = 2^5 and x = 5. The trap is dividing 32 by 2 to get 16 rather than recognizing 32 as 2 to the fifth power." },
  { id: "t18m1-13", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?", type: "mcq", choices: ["10", "12", "14", "48"], correct: 0, explanation: "Goal: apply the Pythagorean theorem. Hypotenuse = √(6² + 8²) = √(36 + 64) = √100 = 10. The trap is adding the legs to get 14 (choice C) instead of using squares." },
  { id: "t18m1-14", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A car travels 150 miles in 3 hours. At this rate, how many miles will it travel in 5 hours?", type: "mcq", choices: ["200", "225", "250", "300"], correct: 2, explanation: "Goal: use a constant rate. The speed is 150/3 = 50 mph, so in 5 hours the car travels 50 × 5 = 250 miles. The trap is adding 150 + 100 incorrectly or using the wrong rate." },
  { id: "t18m1-15", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4x + 2y = 20 and y = 2x, what is the value of x?", type: "mcq", choices: ["2", "2.5", "4", "5"], correct: 1, explanation: "Goal: solve by substitution. Replace y with 2x: 4x + 2(2x) = 20, so 4x + 4x = 20, giving 8x = 20 and x = 2.5. The trap is forgetting to double the substituted term, which would wrongly give x = 3.33." },
  { id: "t18m1-16", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "Which expression is equivalent to (x + 3)(x − 5)?", type: "mcq", choices: ["x² − 2x − 15", "x² + 2x − 15", "x² − 2x + 15", "x² − 8x − 15"], correct: 0, explanation: "Goal: expand the product. Using FOIL: x² − 5x + 3x − 15 = x² − 2x − 15. The trap is mis-signing the middle term; the −5x and +3x combine to −2x, not +2x." },
  { id: "t18m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a class of 30 students, 18 play a sport. What percent of the class plays a sport?", type: "mcq", choices: ["40%", "50%", "60%", "72%"], correct: 2, explanation: "Goal: convert a part-to-whole to a percent. 18/30 = 0.6 = 60%. The trap is computing the non-sport fraction 12/30 = 40% (choice A) instead of the sport fraction." },
  { id: "t18m1-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has radius 5. What is its area? (Use A = πr².)", type: "mcq", choices: ["10π", "20π", "25π", "50π"], correct: 2, explanation: "Goal: find circle area. A = πr² = π(5²) = 25π. The trap is using the circumference formula 2πr = 10π (choice A) or forgetting to square the radius." },
  { id: "t18m1-19", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x − y = 7 and x + y = 5, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve the system. Add the equations to eliminate y: (3x − y) + (x + y) = 7 + 5, so 4x = 12 and x = 3. The trap is subtracting the equations instead of adding, which fails to eliminate y." },
  { id: "t18m1-20", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The function g(x) = 2x² − 3x + 1. What is g(−2)?", type: "grid", gridAnswers: ["15"], explanation: "Goal: evaluate at x = −2. g(−2) = 2(−2)² − 3(−2) + 1 = 2(4) + 6 + 1 = 8 + 6 + 1 = 15. The trap is mishandling signs: −3(−2) is +6, and (−2)² is +4, not −4." },
  { id: "t18m1-21", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A quantity grows by 10% each year. If it starts at 200, what is its value after 2 years?", type: "mcq", choices: ["220", "240", "242", "244"], correct: 2, explanation: "Goal: apply compound growth. After year 1: 200 × 1.10 = 220. After year 2: 220 × 1.10 = 242. The trap is adding 20% once for 240, which ignores the second year's growth on the larger base." },
  { id: "t18m1-22", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have corresponding sides in the ratio 2 to 3. If the smaller triangle has area 8, what is the area of the larger triangle?", type: "mcq", choices: ["12", "16", "18", "27"], correct: 2, explanation: "Goal: scale area by the square of the side ratio. Areas scale as (3/2)² = 9/4, so the larger area is 8 × 9/4 = 18. The trap is scaling area by the side ratio 3/2 to get 12 instead of squaring it." },
];

// ─────────────────────── PRACTICE TEST 18 · MATH M2 easy (22) ────────────────
const T18_MATH_M2E: SatQuestion[] = [
  { id: "t18m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 16, what is the value of x?", type: "mcq", choices: ["5", "6", "7", "8"], correct: 2, explanation: "Goal: solve x + 9 = 16 for x. Set up by isolating x: subtract 9 from both sides. That gives x = 16 − 9, and 16 − 9 = 7. So x = 7. Check by substituting back: 7 + 9 = 16, which matches the original equation. The trap is adding 9 instead of subtracting it, which would give the incorrect 25." },
  { id: "t18m2e-2", section: "math", domain: "Algebra", difficulty: "easy", prompt: "What is 20% of 150?", type: "mcq", choices: ["15", "20", "30", "45"], correct: 2, explanation: "Goal: find 20% of 150. Set up by converting the percent to a decimal: 20% = 0.20, then multiply by 150. That gives 0.20 × 150 = 30. So the answer is 30. Check by scaling: 10% of 150 is 15, and 20% is twice that, 2 × 15 = 30, which agrees. The trap is stopping at 10% and reporting 15 instead of doubling it for 20%." },
  { id: "t18m2e-3", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A recipe uses 2 cups of flour for every 3 cookies. How many cups of flour are needed for 9 cookies?", type: "mcq", choices: ["4", "5", "6", "9"], correct: 2, explanation: "Goal: find the flour needed for 9 cookies given 2 cups per 3 cookies. Set up a proportion: 2 cups / 3 cookies = x cups / 9 cookies. Since 9 is 3 times 3, multiply the flour by the same factor: x = 2 × 3 = 6 cups. So the answer is 6 cups. Check the unit rate: 2/3 cup per cookie times 9 cookies = 6 cups, which matches. The trap is adding the numbers (2 + 3 + 9) or scaling by the wrong factor instead of keeping the ratio constant." },
  { id: "t18m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x − 4, what is y when x = 2?", type: "mcq", choices: ["1", "2", "3", "6"], correct: 1, explanation: "Goal: find y when x = 2 in y = 3x − 4. Set up by substituting x = 2: y = 3(2) − 4. Compute step by step: 3 × 2 = 6, then 6 − 4 = 2. So y = 2. Check by plugging back: with x = 2 the line gives 3(2) − 4 = 2, consistent. The trap is computing only 3 × 2 = 6 and forgetting to subtract the 4, which would wrongly give 6 (choice D)." },
  { id: "t18m2e-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 7. What is its perimeter?", type: "mcq", choices: ["14", "21", "28", "49"], correct: 2, explanation: "Goal: find the perimeter of a square with side 7. Set up using perimeter = 4 × side, since all four sides are equal. That gives 4 × 7 = 28. So the perimeter is 28. Check by adding the four sides: 7 + 7 + 7 + 7 = 28, which agrees. The trap is computing the area instead, 7² = 49 (choice D), or doubling the side to 14 as if it were a rectangle's length-plus-width." },
  { id: "t18m2e-6", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 4²?", type: "mcq", choices: ["8", "12", "16", "24"], correct: 2, explanation: "Goal: evaluate 4². Set up by reading the exponent: 4² means 4 multiplied by itself, 4 × 4. That gives 4 × 4 = 16. So 4² = 16. Check by counting groups: two fours of size 4 give 16, consistent. The trap is doubling the base to get 8 (choice A), which is 4 × 2, instead of squaring it as 4 × 4." },
  { id: "t18m2e-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "The values 5, 7, and 9 have what mean (average)?", type: "mcq", choices: ["6", "7", "8", "9"], correct: 1, explanation: "Goal: find the mean of 5, 7, and 9. Set up the mean as the sum divided by the count of values. Sum: 5 + 7 + 9 = 21. Divide by 3 values: 21 / 3 = 7. So the mean is 7. Check that 7 is the balance point: it is 2 below 9 and 2 above 5, with 7 itself in the middle, so the deviations cancel. The trap is reporting the sum 21 or forgetting to divide by the number of values." },
  { id: "t18m2e-8", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x = 18, what is the value of 3x?", type: "mcq", choices: ["18", "24", "27", "36"], correct: 2, explanation: "Goal: find 3x given 2x = 18. Set up by first solving for x: divide both sides of 2x = 18 by 2, giving x = 9. Then 3x = 3 × 9 = 27. So 3x = 27. Check: 2(9) = 18 confirms x = 9, and tripling gives 27. The trap is stopping at x = 9 and reporting that, or leaving the answer as the original 18 instead of computing 3x." },
  { id: "t18m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "Two angles of a triangle measure 50° and 60°. What is the measure of the third angle?", type: "mcq", choices: ["60°", "70°", "80°", "110°"], correct: 1, explanation: "Goal: find the third angle of a triangle with angles 50° and 60°. Set up using the rule that a triangle's interior angles sum to 180°: third = 180 − 50 − 60. Compute: 50 + 60 = 110, then 180 − 110 = 70. So the third angle is 70°. Check: 50 + 60 + 70 = 180, which matches the angle-sum rule. The trap is stopping at 110° (choice D), the sum of the two given angles, instead of subtracting it from 180°." },
  { id: "t18m2e-10", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A bag holds 4 red and 6 blue marbles. What is the probability of drawing a red marble at random?", type: "grid", gridAnswers: ["0.4", "2/5"], explanation: "Goal: find the probability of drawing a red marble. Set up probability as favorable outcomes over total outcomes. Total marbles = 4 red + 6 blue = 10. Favorable (red) = 4. So P(red) = 4/10, which reduces to 2/5 = 0.4. Check that all probabilities sum to 1: red 4/10 plus blue 6/10 = 10/10 = 1, consistent. The trap is using 4/6, the red-to-blue ratio, instead of red over the total of 10." },
  { id: "t18m2e-11", section: "math", domain: "Algebra", difficulty: "easy", prompt: "Solve for x: x/4 = 6.", type: "grid", gridAnswers: ["24"], explanation: "Goal: solve x/4 = 6 for x. Set up by undoing the division: multiply both sides by 4. That gives x = 6 × 4 = 24. So x = 24. Check by substituting back: 24/4 = 6, which matches the original equation. The trap is dividing 6 by 4 to get 1.5 instead of multiplying, reversing the needed operation." },
  { id: "t18m2e-12", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = 5x + 1, what is f(0)?", type: "mcq", choices: ["0", "1", "5", "6"], correct: 1, explanation: "Goal: find f(0) for f(x) = 5x + 1. Set up by substituting x = 0: f(0) = 5(0) + 1. Compute: 5 × 0 = 0, then 0 + 1 = 1. So f(0) = 1. Check: any function value at x = 0 is just the constant term, which here is 1, consistent. The trap is reporting 5 by ignoring that 5 × 0 = 0, or adding 5 + 1 to get 6 (choice D)." },
  { id: "t18m2e-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells pens at 3 for $1.50. What is the cost of 1 pen?", type: "grid", gridAnswers: ["0.5", "0.50", "1/2"], explanation: "Goal: find the cost of one pen given 3 pens for $1.50. Set up the unit price as total cost divided by quantity: 1.50 / 3. Compute: 1.50 / 3 = 0.50, so one pen costs $0.50. Check by scaling back up: 3 × 0.50 = 1.50, which matches the listed price. The trap is multiplying 1.50 by 3 instead of dividing, which would inflate the per-pen cost." },
  { id: "t18m2e-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 6x − 4 = 2x + 12, what is the value of x?", type: "mcq", choices: ["2", "3", "4", "8"], correct: 2, explanation: "Goal: solve 6x − 4 = 2x + 12 for x. Set up by collecting variable terms on one side: subtract 2x from both sides to get 4x − 4 = 12. Add 4 to both sides: 4x = 16. Divide by 4: x = 4. So x = 4. Check by substituting back: left side 6(4) − 4 = 20, right side 2(4) + 12 = 20, equal. The trap is mishandling the move of 2x across the equals sign and combining it with the wrong sign." },
  { id: "t18m2e-15", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What are the solutions to x² = 49?", type: "mcq", choices: ["7 only", "−7 only", "7 and −7", "0 and 7"], correct: 2, explanation: "Goal: solve x² = 49. Set up by taking the square root of both sides, remembering that a squared variable yields both a positive and a negative root: x = ±√49 = ±7. So the solutions are 7 and −7. Check both: 7² = 49 and (−7)² = 49, since a negative times a negative is positive, so both satisfy the equation. The trap is reporting only the positive root 7 (choice A) and forgetting the negative solution." },
  { id: "t18m2e-16", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has a perimeter of 30 and a length of 9. What is its width?", type: "mcq", choices: ["3", "6", "9", "12"], correct: 1, explanation: "Goal: find the width of a rectangle with perimeter 30 and length 9. Set up the perimeter formula P = 2(length + width): 30 = 2(9 + w). Divide both sides by 2: 15 = 9 + w. Subtract 9: w = 6. So the width is 6. Check: 2(9 + 6) = 2(15) = 30, which matches the given perimeter. The trap is dividing 30 by the length 9 or forgetting to halve the perimeter before subtracting the length." },
  { id: "t18m2e-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A number increased by 25% becomes 50. What was the original number?", type: "mcq", choices: ["25", "37.5", "40", "45"], correct: 2, explanation: "Goal: find the original number that becomes 50 after a 25% increase. Set up the relationship: a 25% increase multiplies the original by 1.25, so 1.25 × original = 50. Solve by dividing: original = 50 / 1.25 = 40. So the original was 40. Check: 40 increased by 25% is 40 + 0.25(40) = 40 + 10 = 50, which matches. The trap is subtracting 25% of 50 (giving 37.5, choice B) instead of dividing by 1.25, since the percent is taken on the original, not on 50." },
  { id: "t18m2e-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "Line ℓ has slope 2 and passes through (1, 5). What is its y-intercept?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the y-intercept b of the line y = 2x + b through (1, 5). Set up by substituting the point's coordinates: 5 = 2(1) + b. Compute 2(1) = 2, so 5 = 2 + b. Subtract 2: b = 3. So the y-intercept is 3. Check: the line y = 2x + 3 at x = 1 gives 2 + 3 = 5, matching the point. The trap is forgetting to subtract the 2(1) term and reporting b = 5, or treating the slope 2 as the intercept." },
  { id: "t18m2e-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If x² + 6x + 9 is written as (x + a)², what is the value of a?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find a so that x² + 6x + 9 = (x + a)². Set up by expanding the target: (x + a)² = x² + 2ax + a². Match coefficients with x² + 6x + 9: the middle term gives 2a = 6, so a = 3, and the constant gives a² = 9. Both yield a = 3. So a = 3. Check: (x + 3)² = x² + 6x + 9, which matches exactly. The trap is reading a = 6 straight off the middle term without halving it to account for the 2a coefficient." },
  { id: "t18m2e-20", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A line of best fit predicts y = 3x + 2. What value of y does it predict when x = 6?", type: "mcq", choices: ["18", "20", "21", "24"], correct: 1, explanation: "Goal: predict y from y = 3x + 2 when x = 6. Set up by substituting x = 6: y = 3(6) + 2. Compute: 3 × 6 = 18, then 18 + 2 = 20. So the predicted y is 20. Check the structure: the slope 3 times 6 gives the variable part 18, and the intercept 2 is added once, giving 20, consistent. The trap is reporting 18 (choice A) by forgetting to add the constant 2." },
  { id: "t18m2e-21", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A cube has edge length 3. What is its volume?", type: "mcq", choices: ["9", "18", "27", "54"], correct: 2, explanation: "Goal: find the volume of a cube with edge 3. Set up using volume = edge³, since a cube's three dimensions are all equal. Compute: 3³ = 3 × 3 × 3 = 27. So the volume is 27. Check stepwise: 3 × 3 = 9 for one face, times the depth 3 gives 27, consistent. The trap is computing a single face area 3² = 9 (choice A) or the total surface area 6 × 9 = 54 (choice D) instead of the volume." },
  { id: "t18m2e-22", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 30, what is the value of x?", type: "mcq", choices: ["5", "6", "7", "31"], correct: 2, explanation: "Goal: solve 5(x − 1) = 30 for x. Set up by dividing both sides by 5 to undo the coefficient: x − 1 = 6. Then add 1 to both sides: x = 7. So x = 7. Check by substituting back: 5(7 − 1) = 5(6) = 30, which matches the original. The trap is forgetting the −1 inside the parentheses and reporting x = 6 (choice B) instead of adding 1." },
];

