const T18_MATH_M2H: SatQuestion[] = [
  { id: "t18m2h-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3x − 7 = 2x + 5, what is the value of x?", type: "mcq", choices: ["10", "12", "−2", "2"], correct: 1, explanation: "Goal: solve the linear equation. Subtract 2x: x − 7 = 5. Add 7: x = 12. The trap is mishandling the sign when moving −7 across, which would give x = −2." },
  { id: "t18m2h-2", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "The product of the roots of x² − 6x + 8 = 0 is what value?", type: "mcq", choices: ["2", "4", "6", "8"], correct: 3, explanation: "Goal: find the product of roots. Factoring gives (x − 2)(x − 4) = 0, so the roots are 2 and 4 and their product is 8. Equivalently, for ax² + bx + c the product is c/a = 8. The trap is reporting the sum 6 (choice C)." },
  { id: "t18m2h-3", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A store marks up a $60 item by 30% and then offers a 10% discount on the marked-up price. What is the final price?", type: "mcq", choices: ["$66.00", "$70.20", "$72.00", "$78.00"], correct: 1, explanation: "Goal: apply successive percent changes. Marked-up price = 60 × 1.30 = $78. After 10% off: 78 × 0.90 = $70.20. The trap is treating +30% then −10% as a net +20% to get $72, which ignores that the discount applies to the larger marked-up price." },
  { id: "t18m2h-4", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 2x + 3y = 16 and x = 2, what is the value of y?", type: "grid", gridAnswers: ["4"], explanation: "Goal: substitute and solve. Replace x: 2(2) + 3y = 16, so 4 + 3y = 16, giving 3y = 12 and y = 4. The trap is forgetting to subtract the 4 before dividing by 3." },
  { id: "t18m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "In a right triangle, one acute angle is 30°. If the hypotenuse is 10, what is the length of the side opposite the 30° angle?", type: "mcq", choices: ["5", "5√3", "10", "20"], correct: 0, explanation: "Goal: use a trig ratio. The side opposite 30° equals hypotenuse × sin(30°) = 10 × 0.5 = 5. The trap is using cos(30°) and getting 5√3, which is the side adjacent to the 30° angle." },
  { id: "t18m2h-6", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If 3^(x+1) = 81, what is the value of x?", type: "mcq", choices: ["2", "3", "4", "27"], correct: 1, explanation: "Goal: solve the exponential equation. Write 81 as 3^4, so 3^(x+1) = 3^4, giving x + 1 = 4 and x = 3. The trap is solving x + 1 = 4 but forgetting to subtract 1, reporting x = 4 (choice C)." },
  { id: "t18m2h-7", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A sample of 50 voters had 30 in favor of a measure. If the full population of 5,000 voters behaves the same way, about how many favor the measure?", type: "mcq", choices: ["1,500", "2,500", "3,000", "3,500"], correct: 2, explanation: "Goal: scale a proportion. In the sample 30/50 = 0.6 favored the measure, so 0.6 × 5,000 = 3,000. The trap is using 30/5,000 or scaling by the wrong base." },
  { id: "t18m2h-8", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 24 and 2x − 3y = 6, what is the value of x?", type: "mcq", choices: ["3", "4", "5", "6"], correct: 2, explanation: "Goal: solve the system by elimination. Add the equations: (4x + 3y) + (2x − 3y) = 24 + 6, so 6x = 30 and x = 5. The trap is subtracting the equations, which fails to cancel the y terms here." },
  { id: "t18m2h-9", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The vertex of the parabola y = x² − 8x + 12 has what x-coordinate?", type: "mcq", choices: ["−4", "2", "4", "8"], correct: 2, explanation: "Goal: find the vertex's x-coordinate. Use x = −b/(2a) = −(−8)/(2·1) = 8/2 = 4. The trap is dropping the negative sign on b and getting −4 (choice A) instead of 4." },
  { id: "t18m2h-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 3 and height 5. What is its volume? (Use V = πr²h.)", type: "mcq", choices: ["15π", "30π", "45π", "75π"], correct: 2, explanation: "Goal: find cylinder volume. V = πr²h = π(3²)(5) = π(9)(5) = 45π. The trap is forgetting to square the radius and computing π(3)(5) = 15π (choice A)." },
  { id: "t18m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A phone plan costs $30 plus $0.10 per minute. If a bill is $48, how many minutes were used?", type: "mcq", choices: ["120", "150", "180", "480"], correct: 2, explanation: "Goal: solve for minutes. Set 30 + 0.10m = 48, so 0.10m = 18 and m = 180. The trap is dividing 48 by 0.10 (giving 480) without first subtracting the $30 base fee." },
  { id: "t18m2h-12", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If (x − 4) is a factor of x² − 4x + k, what is the value of k?", type: "mcq", choices: ["−4", "0", "4", "16"], correct: 1, explanation: "Goal: use the factor theorem. If (x − 4) is a factor, then x = 4 is a root: 4² − 4(4) + k = 0, so 16 − 16 + k = 0 and k = 0. The trap is leaving k = 16 from only the 4² term without subtracting 4(4)." },
  { id: "t18m2h-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria doubles every hour. If there are 250 at noon, how many are there at 3 p.m.?", type: "mcq", choices: ["750", "1,000", "1,500", "2,000"], correct: 3, explanation: "Goal: apply repeated doubling. Three hours means doubling 3 times: 250 × 2³ = 250 × 8 = 2,000. The trap is multiplying by 3 (giving 750) instead of by 2 three times." },
  { id: "t18m2h-14", section: "math", domain: "Algebra", difficulty: "hard", prompt: "The line through (2, 3) and (6, 11) has what y-intercept?", type: "mcq", choices: ["−1", "1", "2", "3"], correct: 0, explanation: "Goal: find the y-intercept. Slope = (11 − 3)/(6 − 2) = 8/4 = 2. Using y = 2x + b with (2, 3): 3 = 2(2) + b, so b = 3 − 4 = −1. The trap is sign errors when solving for b, or using the slope as the intercept." },
  { id: "t18m2h-15", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² − 2x and f(a) = 8, which positive value of a satisfies the equation?", type: "mcq", choices: ["2", "3", "4", "5"], correct: 2, explanation: "Goal: solve f(a) = 8. Set a² − 2a = 8, so a² − 2a − 8 = 0, which factors as (a − 4)(a + 2) = 0, giving a = 4 or a = −2. The positive value is 4. The trap is choosing −2 or stopping before factoring." },
  { id: "t18m2h-16", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A circle has circumference 12π. What is its area? (Use C = 2πr and A = πr².)", type: "mcq", choices: ["12π", "24π", "36π", "144π"], correct: 2, explanation: "Goal: get the radius, then the area. From C = 2πr = 12π, r = 6. Area = πr² = π(36) = 36π. The trap is using the circumference value as if it were the radius, or forgetting to square r." },
  { id: "t18m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The mean of five numbers is 12. If four of the numbers are 10, 11, 13, and 14, what is the fifth number?", type: "grid", gridAnswers: ["12"], explanation: "Goal: use the total implied by the mean. The five numbers sum to 5 × 12 = 60. The four known values total 10 + 11 + 13 + 14 = 48, so the fifth is 60 − 48 = 12. The trap is averaging the four numbers instead of using the total of all five." },
  { id: "t18m2h-18", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/(2x) = 3/4, what is the value of x?", type: "grid", gridAnswers: ["2"], explanation: "Goal: solve the equation with fractions. Combine the left side: 1/x + 1/(2x) = 2/(2x) + 1/(2x) = 3/(2x). Set 3/(2x) = 3/4, so 2x = 4 and x = 2. The trap is adding the denominators directly instead of finding a common denominator." },
  { id: "t18m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 10x + 25 = 0, what is the value of x?", type: "mcq", choices: ["−5", "0", "5", "10"], correct: 2, explanation: "Goal: solve the quadratic. It is a perfect square: x² − 10x + 25 = (x − 5)² = 0, so x = 5 is the only (double) root. The trap is taking the constant 25's root or choosing −5 with the wrong sign." },
  { id: "t18m2h-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A 12-foot ladder leans against a wall, reaching a height of 9 feet. How far is the base of the ladder from the wall? (Round to one decimal.)", type: "grid", gridAnswers: ["7.9"], explanation: "Goal: apply the Pythagorean theorem. The base distance is √(12² − 9²) = √(144 − 81) = √63 ≈ 7.9 feet. The trap is subtracting 12 − 9 = 3 instead of using the squares of the sides." },
  { id: "t18m2h-21", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "An investment of $400 earns 5% simple interest per year. What is its total value after 3 years?", type: "mcq", choices: ["$420", "$440", "$460", "$463"], correct: 2, explanation: "Goal: apply simple interest. Interest = 400 × 0.05 × 3 = $60, so the total is 400 + 60 = $460. The trap is computing compound interest (about $463) or only one year of interest." },
  { id: "t18m2h-22", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x is a positive number and x² + 4x = 21, what is the value of x?", type: "grid", gridAnswers: ["3"], explanation: "Goal: solve the quadratic for the positive root. Rewrite as x² + 4x − 21 = 0, which factors as (x + 7)(x − 3) = 0, giving x = −7 or x = 3. Since x is positive, x = 3. The trap is choosing −7 or mis-factoring the constant 21." },
];

